// src/constants/mapConfig.js
export const UCN_COQUIMBO_BOUNDS = [
  [-29.96800, -71.35200], // Más al oeste (longitud más negativa)
  [-29.96200, -71.34800]  // Más al oeste (longitud más negativa)
];

export const MAP_ZOOM_LIMITS = {
  min: 17,
  max: 19,
  default: 18
};

export const GEO_SERVER_CONFIG = {
  baseUrl: 'http://localhost:8080/geoserver',
  workspace: 'InteractiveMap',
  layerName: 'edificio'
};
